java('interprocedural/CallResolver','''import io.github.cheshmakzanoon.portfolio.byteguard.bytecode.*;import java.util.*;
public final class CallResolver {private final TypeHierarchy hierarchy;public CallResolver(TypeHierarchy hierarchy){this.hierarchy=hierarchy;}public List<String> resolve(String owner,String name,String desc,int opcode){return hierarchy.targets(owner,name,desc,opcode==org.objectweb.asm.Opcodes.INVOKEVIRTUAL||opcode==org.objectweb.asm.Opcodes.INVOKEINTERFACE);}}
''')
java('dataflow/TransferFunction','''import io.github.cheshmakzanoon.portfolio.byteguard.bytecode.*;import io.github.cheshmakzanoon.portfolio.byteguard.interprocedural.*;import io.github.cheshmakzanoon.portfolio.byteguard.rules.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import java.util.*;
/** Original JVM computational-value transfer. Category-two values occupy one stack cell/two local slots. */
public final class TransferFunction implements Opcodes {
 private final MethodIr method;private final HeapSummary heap;private final RuleModels models;private final CallResolver resolver;private final Map<String,MethodSummary> summaries;private final AnalysisBudget budget;private final Set<String> diagnostics;private final SortedMap<String,MethodSummary.Flow> flows=new TreeMap<>();private Taint returns=Taint.BOTTOM;
 public TransferFunction(MethodIr method,HeapSummary heap,RuleModels models,CallResolver resolver,Map<String,MethodSummary> summaries,AnalysisBudget budget,Set<String> diagnostics){this.method=method;this.heap=heap;this.models=models;this.resolver=resolver;this.summaries=summaries;this.budget=budget;this.diagnostics=diagnostics;}
 public MethodSummary summary(){return new MethodSummary(returns,flows);}
 private AbstractValue value(AbstractValue.Kind kind,Taint taint){return AbstractValue.of(kind,taint);}private void unary(FrameState f,AbstractValue.Kind k){f.push(value(k,f.pop().taint()));}private void binary(FrameState f,AbstractValue.Kind k){Taint t=f.pop().taint().join(f.pop().taint());f.push(value(k,t));}
 public void apply(int ordinal,FrameState f){AbstractInsnNode n=method.instructions.get(ordinal);int op=n.getOpcode();InstructionId site=method.at(ordinal);switch(op){
 case NOP->{}case ACONST_NULL->f.push(AbstractValue.constant("null"));case ICONST_M1,ICONST_0,ICONST_1,ICONST_2,ICONST_3,ICONST_4,ICONST_5->f.push(AbstractValue.constant(op-ICONST_0));case LCONST_0,LCONST_1->f.push(AbstractValue.constant((long)(op-LCONST_0)));case FCONST_0,FCONST_1,FCONST_2->f.push(AbstractValue.constant((float)(op-FCONST_0)));case DCONST_0,DCONST_1->f.push(AbstractValue.constant((double)(op-DCONST_0)));case BIPUSH,SIPUSH->f.push(AbstractValue.constant(((IntInsnNode)n).operand));case LDC->f.push(AbstractValue.constant(((LdcInsnNode)n).cst));
 case ILOAD,LLOAD,FLOAD,DLOAD,ALOAD->{AbstractValue v=f.locals[((VarInsnNode)n).var];if(v.kind()==AbstractValue.Kind.TOP)throw new IllegalArgumentException("load undefined local at "+site);f.push(v);}case ISTORE,LSTORE,FSTORE,DSTORE,ASTORE->f.store(((VarInsnNode)n).var,f.pop());case IINC->{int slot=((IincInsnNode)n).var;if(f.locals[slot].kind()!=AbstractValue.Kind.INT)throw new IllegalArgumentException("iinc on non-int");}
 case POP->{if(f.pop().size()!=1)throw new IllegalArgumentException("pop category two");}case POP2->{if(f.pop().size()==1&&f.pop().size()!=1)throw new IllegalArgumentException("invalid pop2");}case DUP,DUP_X1,DUP_X2,DUP2,DUP2_X1,DUP2_X2,SWAP->duplicate(op,f);
 case IADD,ISUB,IMUL,IDIV,IREM,ISHL,ISHR,IUSHR,IAND,IOR,IXOR,LCMP,FCMPL,FCMPG,DCMPL,DCMPG->binary(f,AbstractValue.Kind.INT);case LADD,LSUB,LMUL,LDIV,LREM,LSHL,LSHR,LUSHR,LAND,LOR,LXOR->binary(f,AbstractValue.Kind.LONG);case FADD,FSUB,FMUL,FDIV,FREM->binary(f,AbstractValue.Kind.FLOAT);case DADD,DSUB,DMUL,DDIV,DREM->binary(f,AbstractValue.Kind.DOUBLE);
 case INEG,I2B,I2C,I2S,L2I,F2I,D2I->unary(f,AbstractValue.Kind.INT);case LNEG,I2L,F2L,D2L->unary(f,AbstractValue.Kind.LONG);case FNEG,I2F,L2F,D2F->unary(f,AbstractValue.Kind.FLOAT);case DNEG,I2D,L2D,F2D->unary(f,AbstractValue.Kind.DOUBLE);
 case IFEQ,IFNE,IFLT,IFGE,IFGT,IFLE,IFNULL,IFNONNULL,TABLESWITCH,LOOKUPSWITCH->f.pop();case IF_ICMPEQ,IF_ICMPNE,IF_ICMPLT,IF_ICMPGE,IF_ICMPGT,IF_ICMPLE,IF_ACMPEQ,IF_ACMPNE->{f.pop();f.pop();}case GOTO->{}case JSR,RET->throw new IllegalArgumentException("legacy jsr/ret unsupported: "+site);
 case IRETURN,LRETURN,FRETURN,DRETURN,ARETURN->returns=returns.join(heap.elements(f.pop()));case RETURN->{}case ATHROW->f.pop();
 case NEW->f.push(AbstractValue.reference(Taint.BOTTOM,"new:"+site));case NEWARRAY,ANEWARRAY->{Taint t=f.pop().taint();f.push(AbstractValue.reference(t,"array:"+site));}case MULTIANEWARRAY->{Taint t=Taint.BOTTOM;for(int i=0;i<((MultiANewArrayInsnNode)n).dims;i++)t=t.join(f.pop().taint());f.push(AbstractValue.reference(t,"array:"+site));}
 case IALOAD,BALOAD,CALOAD,SALOAD,LALOAD,FALOAD,DALOAD,AALOAD->{Taint index=f.pop().taint();AbstractValue array=f.pop();AbstractValue.Kind kind=switch(op){case LALOAD->AbstractValue.Kind.LONG;case FALOAD->AbstractValue.Kind.FLOAT;case DALOAD->AbstractValue.Kind.DOUBLE;case AALOAD->AbstractValue.Kind.REF;default->AbstractValue.Kind.INT;};f.push(value(kind,heap.elements(array).join(index)));}
 case IASTORE,LASTORE,FASTORE,DASTORE,AASTORE,BASTORE,CASTORE,SASTORE->{AbstractValue v=f.pop();f.pop();AbstractValue array=f.pop();heap.addElement(array,heap.elements(v));if(v.constant()!=null)for(String ref:array.references())heap.write(ref+"#const:"+v.constant(),Taint.source("CONST"));}
 case ARRAYLENGTH->{f.pop();f.push(value(AbstractValue.Kind.INT,Taint.BOTTOM));}case CHECKCAST->{}case INSTANCEOF->{f.pop();f.push(value(AbstractValue.Kind.INT,Taint.BOTTOM));}case MONITORENTER,MONITOREXIT->f.pop();
 case GETFIELD,GETSTATIC->{FieldInsnNode field=(FieldInsnNode)n;if(op==GETFIELD)f.pop();f.push(value(AbstractValue.kind(Type.getType(field.desc)),heap.read(field.owner+"."+field.name+field.desc)));}case PUTFIELD,PUTSTATIC->{FieldInsnNode field=(FieldInsnNode)n;AbstractValue v=f.pop();if(op==PUTFIELD)f.pop();heap.write(field.owner+"."+field.name+field.desc,heap.elements(v));}
 case INVOKESTATIC,INVOKESPECIAL,INVOKEVIRTUAL,INVOKEINTERFACE->call((MethodInsnNode)n,f,site);case INVOKEDYNAMIC->dynamic((InvokeDynamicInsnNode)n,f,site);
 default->throw new IllegalArgumentException("unsupported opcode "+op+" at "+site);
 }if(f.slots()>method.node.maxStack)throw new IllegalArgumentException("maxStack exceeded: "+site);}
 private void duplicate(int opcode,FrameState f){AbstractValue a=f.pop(),b,c,d;switch(opcode){case DUP->{cat1(a);f.push(a);f.push(a);}case SWAP->{b=f.pop();cat1(a);cat1(b);f.push(a);f.push(b);}case DUP_X1->{b=f.pop();cat1(a);cat1(b);f.push(a);f.push(b);f.push(a);}case DUP_X2->{cat1(a);b=f.pop();if(b.size()==2){f.push(a);f.push(b);f.push(a);}else{c=f.pop();cat1(c);f.push(a);f.push(c);f.push(b);f.push(a);}}case DUP2->{if(a.size()==2){f.push(a);f.push(a);}else{b=f.pop();cat1(b);f.push(b);f.push(a);f.push(b);f.push(a);}}case DUP2_X1->{if(a.size()==2){b=f.pop();cat1(b);f.push(a);f.push(b);f.push(a);}else{b=f.pop();c=f.pop();cat1(b);cat1(c);f.push(b);f.push(a);f.push(c);f.push(b);f.push(a);}}case DUP2_X2->{if(a.size()==2){b=f.pop();if(b.size()==2){f.push(a);f.push(b);f.push(a);}else{c=f.pop();cat1(c);f.push(a);f.push(c);f.push(b);f.push(a);}}else{b=f.pop();cat1(b);c=f.pop();if(c.size()==2){f.push(b);f.push(a);f.push(c);f.push(b);f.push(a);}else{d=f.pop();cat1(d);f.push(b);f.push(a);f.push(d);f.push(c);f.push(b);f.push(a);}}}default->throw new IllegalArgumentException("bad duplication");}}
 private void cat1(AbstractValue value){if(value.size()!=1)throw new IllegalArgumentException("invalid duplication category");}
 private void dynamic(InvokeDynamicInsnNode n,FrameState f,InstructionId site){Type[] types=Type.getArgumentTypes(n.desc);Taint t=Taint.BOTTOM;for(int i=types.length-1;i>=0;i--)t=t.join(heap.elements(f.pop()));String owner=n.bsm.getOwner();if(owner.equals("java/lang/invoke/StringConcatFactory")){f.push(value(AbstractValue.Kind.REF,t));}else if(owner.equals("java/lang/invoke/LambdaMetafactory")){String target="lambda:"+site;for(Object arg:n.bsmArgs)if(arg instanceof Handle h)target="lambda:"+h.getOwner()+"."+h.getName()+h.getDesc();f.push(AbstractValue.reference(t,target));}else{diagnostics.add("UNSUPPORTED_BOOTSTRAP "+site+" "+owner);f.push(value(AbstractValue.kind(Type.getReturnType(n.desc)),t.join(Taint.unknownValue())));}}
 private void call(MethodInsnNode n,FrameState f,InstructionId site){Type[] types=Type.getArgumentTypes(n.desc);ArrayList<AbstractValue> args=new ArrayList<>();for(int i=types.length-1;i>=0;i--)args.addFirst(f.pop());AbstractValue receiver=n.getOpcode()==INVOKESTATIC?AbstractValue.of(AbstractValue.Kind.REF,Taint.BOTTOM):f.pop();String id=n.owner+"."+n.name+n.desc;Taint joined=heap.elements(receiver);for(AbstractValue arg:args)joined=joined.join(heap.elements(arg));Taint returned=Taint.BOTTOM;SortedSet<String> resultRefs=new TreeSet<>();
 RuleModels.Sink sink=models.sink(id);if(sink!=null&&args.size()>sink.argument())flow(sink.id(),sink.mask(),site,id,heap.elements(args.get(sink.argument())),List.of(method.id),false);
 if(n.owner.equals("java/lang/Runtime")&&n.name.equals("exec")&&n.desc.startsWith("([Ljava/lang/String;")){AbstractValue commands=args.getFirst();if(shell(commands))flow("BG-SHELL-COMMAND",2,site,id,heap.elements(commands),List.of(method.id),false);}
 if(n.owner.equals("java/lang/ProcessBuilder")&&n.name.equals("<init>")){heap.addElement(receiver,joined);if(!args.isEmpty()&&shell(args.getFirst()))for(String ref:receiver.references())heap.write(ref+"#shell",Taint.source("CONST"));}
 if(n.owner.equals("java/lang/ProcessBuilder")&&n.name.equals("start")&&receiver.references().stream().anyMatch(r->!heap.read(r+"#shell").equals(Taint.BOTTOM)))flow("BG-SHELL-COMMAND",2,site,id,heap.elements(receiver),List.of(method.id),false);
 if(models.source(id))returned=Taint.source(site.toString()+"|"+id);
 else if(models.sanitizer(id)!=0)returned=joined.sanitize(models.sanitizer(id));
 else if(n.owner.equals("java/lang/StringBuilder")||n.owner.equals("java/lang/StringBuffer")){if(n.name.equals("append")||n.name.equals("<init>"))heap.addElement(receiver,joined);returned=heap.elements(receiver).join(joined);resultRefs.addAll(receiver.references());}
 else if(n.owner.equals("java/lang/String")||n.owner.equals("java/lang/CharSequence")||n.owner.equals("java/nio/file/Path")||n.owner.equals("java/nio/file/Paths")||n.owner.equals("java/io/File")||n.owner.matches("java/lang/(Integer|Long|Double|Float|Boolean|Character|Short|Byte)")){returned=joined;}
 else if(n.owner.startsWith("java/util/")&&(n.owner.contains("List")||n.owner.contains("Collection")||n.owner.contains("Map")||n.owner.contains("Set")||n.owner.contains("Iterator")||n.owner.contains("Optional"))){if(Set.of("add","put","set","offer","push","<init>").contains(n.name))heap.addElement(receiver,joined);returned=heap.elements(receiver).join(joined);resultRefs.addAll(receiver.references());}
 else if(n.owner.startsWith("java/util/function/")&&!receiver.references().isEmpty()){returned=joined;for(String ref:receiver.references())if(ref.startsWith("lambda:")){MethodSummary summary=summaries.get(ref.substring(7));if(summary!=null){List<Taint> actual=new ArrayList<>();actual.add(heap.elements(receiver));for(AbstractValue a:args)actual.add(heap.elements(a));returned=returned.join(summary.returns().substitute(actual));importFlows(summary,actual,site);}}}
 else {List<String> targets=resolver.resolve(n.owner,n.name,n.desc,n.getOpcode());if(targets.size()>budget.dispatchTargets){diagnostics.add("DISPATCH_LIMIT "+site+" targets="+targets.size()+" limit="+budget.dispatchTargets);returned=joined.join(Taint.unknownValue());}else if(!targets.isEmpty()){List<Taint> actual=new ArrayList<>();if(n.getOpcode()!=INVOKESTATIC)actual.add(heap.elements(receiver));for(AbstractValue a:args)actual.add(heap.elements(a));for(String target:targets){MethodSummary summary=summaries.getOrDefault(target,MethodSummary.empty());returned=returned.join(summary.returns().substitute(actual));importFlows(summary,actual,site);}}else if(knownInert(id,n)){returned=joined;}else {diagnostics.add("UNKNOWN_CALL "+site+" "+id);returned=joined.join(Taint.unknownValue());}}
 Type ret=Type.getReturnType(n.desc);if(ret.getSort()!=Type.VOID)f.push(new AbstractValue(AbstractValue.kind(ret),returned,resultRefs,null));}
 private boolean shell(AbstractValue value){boolean command=false,flag=false;for(String ref:value.references()){command|=!heap.read(ref+"#const:/bin/sh").equals(Taint.BOTTOM)||!heap.read(ref+"#const:sh").equals(Taint.BOTTOM)||!heap.read(ref+"#const:/bin/bash").equals(Taint.BOTTOM);flag|=!heap.read(ref+"#const:-c").equals(Taint.BOTTOM);}return command&&flag;}
 private boolean knownInert(String id,MethodInsnNode n){return n.name.equals("<init>")&&n.owner.startsWith("java/")||n.owner.equals("java/lang/Runtime")&&n.name.equals("getRuntime")||n.owner.equals("java/lang/Math")||n.owner.equals("java/lang/Object")||n.owner.equals("java/sql/PreparedStatement")&&n.name.startsWith("set")||n.owner.equals("java/sql/Statement")||n.owner.equals("java/sql/Connection")||n.owner.equals("java/nio/file/Files")||n.owner.equals("java/lang/ProcessBuilder")||n.owner.equals("java/lang/Runtime");}
 private void importFlows(MethodSummary summary,List<Taint> actual,InstructionId site){for(MethodSummary.Flow old:summary.flows().values()){ArrayList<String> path=new ArrayList<>();path.add(site.toString());path.addAll(old.callPath());boolean truncated=old.truncated()||path.size()>budget.provenanceDepth;if(path.size()>budget.provenanceDepth)path=new ArrayList<>(path.subList(0,budget.provenanceDepth));flow(old.rule(),old.mask(),old.sink(),old.descriptor(),old.taint().substitute(actual),path,truncated);}}
 private void flow(String rule,int mask,InstructionId sink,String descriptor,Taint taint,List<String> path,boolean truncated){if(taint.labels().values().stream().noneMatch(v->(v&mask)!=0)&&!taint.unknown())return;String key=rule+"|"+sink;MethodSummary.Flow next=new MethodSummary.Flow(rule,mask,sink,descriptor,taint,path,truncated);MethodSummary.Flow old=flows.get(key);if(old==null)flows.put(key,next);else flows.put(key,new MethodSummary.Flow(rule,mask,sink,descriptor,old.taint().join(taint),old.callPath(),old.truncated()||truncated));}
}''')
java('dataflow/WorklistSolver','''import io.github.cheshmakzanoon.portfolio.byteguard.bytecode.*;import io.github.cheshmakzanoon.portfolio.byteguard.cfg.*;import io.github.cheshmakzanoon.portfolio.byteguard.interprocedural.*;import org.objectweb.asm.*;import java.util.*;
public final class WorklistSolver {
 public record Result(MethodSummary summary,List<FrameState> frames,int reachable){}
 public Result solve(MethodIr method,ControlFlowBuilder.Graph graph,TransferFunction transfer,AnalysisBudget budget,boolean reverse){int n=method.instructions.size();if(n==0)return new Result(MethodSummary.empty(),List.of(),0);FrameState[] states=new FrameState[n];FrameState initial=new FrameState(method.node.maxLocals);int slot=0,param=0;if((method.node.access&Opcodes.ACC_STATIC)==0)initial.store(slot++,AbstractValue.reference(Taint.source("P:"+param++),"this:"+method.id));for(Type type:Type.getArgumentTypes(method.node.desc)){AbstractValue v=AbstractValue.of(AbstractValue.kind(type),Taint.source("P:"+param++));if(v.kind()==AbstractValue.Kind.REF)v=AbstractValue.reference(v.taint(),"parameter:"+method.id+":"+slot);initial.store(slot,v);slot+=type.getSize();}states[0]=initial;Deque<Integer> pending=new ArrayDeque<>();BitSet queued=new BitSet();pending.add(0);queued.set(0);while(!pending.isEmpty()){int i=reverse?pending.removeLast():pending.removeFirst();queued.clear(i);budget.spend();FrameState before=states[i];FrameState after=before.copy();transfer.apply(i,after);for(int to:graph.normal().get(i))propagate(to,after,states,pending,queued);for(int to:graph.exceptional().get(i)){FrameState handler=before.copy();handler.stack.clear();handler.push(AbstractValue.of(AbstractValue.Kind.REF,before.stackTaint().join(Taint.unknownValue())));propagate(to,handler,states,pending,queued);}}
 int reached=0;for(FrameState state:states)if(state!=null)reached++;return new Result(transfer.summary(),Collections.unmodifiableList(Arrays.asList(states)),reached);}
 private void propagate(int target,FrameState frame,FrameState[] states,Deque<Integer> pending,BitSet queued){boolean changed;if(states[target]==null){states[target]=frame.copy();changed=true;}else changed=states[target].merge(frame);if(changed&&!queued.get(target)){pending.addLast(target);queued.set(target);}}
}''')
java('interprocedural/SummaryWorklist','''import io.github.cheshmakzanoon.portfolio.byteguard.bytecode.*;import io.github.cheshmakzanoon.portfolio.byteguard.cfg.*;import io.github.cheshmakzanoon.portfolio.byteguard.dataflow.*;import io.github.cheshmakzanoon.portfolio.byteguard.rules.*;import java.util.*;
public final class SummaryWorklist {
 public record Result(SortedMap<String,MethodSummary> summaries,SortedSet<String> diagnostics,boolean partial,List<String> unfinished,long work,Map<String,WorklistSolver.Result> methods,List<List<String>> recursiveComponents){}
 public Result analyze(SortedMap<String,ClassFactsReader.ClassFacts> classes,AnalysisBudget budget,boolean reverse){TreeMap<String,MethodIr> methods=new TreeMap<>();Set<String> application=new HashSet<>();classes.values().forEach(c->{methods.putAll(c.methods());if(c.application())application.addAll(c.methods().keySet());});TreeMap<String,MethodSummary> summaries=new TreeMap<>();TreeSet<String> diagnostics=new TreeSet<>();Map<String,WorklistSolver.Result> results=new TreeMap<>();HeapSummary heap=new HeapSummary();CallResolver resolver=new CallResolver(new TypeHierarchy(classes));Map<String,ControlFlowBuilder.Graph> graphs=new TreeMap<>();methods.forEach((k,v)->graphs.put(k,new ControlFlowBuilder().build(v)));Map<String,Collection<String>> calls=new TreeMap<>();for(MethodIr m:methods.values()){TreeSet<String> targets=new TreeSet<>();for(var n:m.instructions)if(n instanceof org.objectweb.asm.tree.MethodInsnNode call)targets.addAll(resolver.resolve(call.owner,call.name,call.desc,call.getOpcode()));calls.put(m.id,targets);}List<List<String>> components=new StronglyConnectedComponents().find(calls);List<String> order=new ArrayList<>();for(List<String> c:components)order.addAll(c);if(reverse)Collections.reverse(order);Deque<String> pending=new ArrayDeque<>(order);Set<String> queued=new HashSet<>(order);String current="";boolean partial=false;List<String> unfinished=new ArrayList<>();try{while(!pending.isEmpty()){current=pending.removeFirst();queued.remove(current);MethodIr m=methods.get(current);TransferFunction transfer=new TransferFunction(m,heap,new RuleModels(),resolver,summaries,budget,diagnostics);WorklistSolver.Result result=new WorklistSolver().solve(m,graphs.get(current),transfer,budget,reverse);results.put(current,result);MethodSummary old=summaries.getOrDefault(current,MethodSummary.empty()),next=old.join(result.summary());if(!old.equals(next)||heap.consumeChanged()){summaries.put(current,next);for(String id:order)if(queued.add(id))pending.addLast(id);}}}catch(AnalysisBudget.Exhausted exhausted){partial=true;diagnostics.add("RESOURCE_LIMIT "+exhausted.getMessage());unfinished.add(current);unfinished.addAll(pending);}for(String diagnostic:diagnostics)if(diagnostic.startsWith("DISPATCH_LIMIT")||diagnostic.startsWith("UNSUPPORTED_BOOTSTRAP")){partial=true;if(unfinished.isEmpty())unfinished.add(diagnostic);}TreeMap<String,MethodSummary> app=new TreeMap<>();summaries.forEach((k,v)->{if(application.contains(k))app.put(k,v);});return new Result(app,diagnostics,partial,List.copyOf(unfinished),budget.work(),Collections.unmodifiableMap(results),components);}
}''')
java('interprocedural/Analyzer','''import io.github.cheshmakzanoon.portfolio.byteguard.input.*;import io.github.cheshmakzanoon.portfolio.byteguard.bytecode.*;import java.util.*;import java.io.*;import java.nio.file.*;
public final class Analyzer {
 public record Result(InputManifest manifest,SortedMap<String,ClassFactsReader.ClassFacts> classes,SummaryWorklist.Result analysis){}
 public Result scan(List<Path> input,List<Path> classpath,int release,InputLimits limits,AnalysisBudget budget)throws IOException{InputManifest manifest=new BoundedJarReader(limits,release).read(input,classpath);var classes=new ClassFactsReader().read(manifest);try{return new Result(manifest,classes,new SummaryWorklist().analyze(classes,budget,false));}catch(IllegalArgumentException e){throw new InputFailure("invalid/unsupported bytecode: "+e.getMessage());}}
}''')
